type PrepareFreshResumeClaimParams struct {
	WorkerID pgtype.UUID `json:"worker_id"`
	RunID    uuid.UUID   `json:"run_id"`
	ID       uuid.UUID   `json:"id"`
}

type PrepareFreshResumeClaimRow struct {
	ID                  uuid.UUID   `json:"id"`
	UserID              uuid.UUID   `json:"user_id"`
	Status              string      `json:"status"`
	WorkerID            pgtype.UUID `json:"worker_id"`
	BudgetPausedSeconds int32       `json:"budget_paused_seconds"`
}

// Saves the run's pre-claim tuple into the pending transfer row, then queues the run for W2 with the
// paused-time credit and clears of ResumeWorkerRecoveryEpisode (same SET list, except that
// worker_recovery_episode is untouched: ADR-1197's grant and high-water mark are kept, and
// codex_cap_hash / codex_claim_epoch stay monotonic for ClaimRun). Requires the opt-in for this row.
func (q *Queries) PrepareFreshResumeClaim(ctx context.Context, arg PrepareFreshResumeClaimParams) (PrepareFreshResumeClaimRow, error) {
	row := q.db.QueryRow(ctx, prepareFreshResumeClaim, arg.WorkerID, arg.RunID, arg.ID)
	var i PrepareFreshResumeClaimRow
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Status,
		&i.WorkerID,
		&i.BudgetPausedSeconds,
	)
	return i, err
}

